function cssText(pairs) { return pairs.join(";"); }

// 让 DOM 元素可点击：恢复 pointer-events 并阻止事件冒泡到画布（否则会拖动节点）
function clickable(el) {
    el.style.pointerEvents = "auto";
    el.style.cursor = "pointer";
    for (const ev of ["mousedown", "mouseup", "click", "dblclick"]) {
        el.addEventListener(ev, (e) => e.stopPropagation());
    }
    return el;
}
// 点击复制文本（带降级）
function copyText(text, okEl) {
    const done = () => { const old = okEl.textContent; okEl.textContent = "已复制 ✓";
        setTimeout(() => { okEl.textContent = old; }, 1200); };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done).catch(() => fallback());
    } else fallback();
    function fallback() {
        const ta = document.createElement("textarea");
        ta.value = text; ta.style.position = "fixed"; ta.style.opacity = "0";
        document.body.appendChild(ta); ta.select();
        try { document.execCommand("copy"); done(); } catch (e) {}
        document.body.removeChild(ta);
    }
}

// 造一个二维码卡片：标题 + 图片 + 一行说明
function makeQrCard(title, src, caption, accent) {
    const card = document.createElement("div");
    card.style.cssText = cssText([
        "flex:1", "min-width:0", "display:flex", "flex-direction:column",
        "align-items:center", "gap:6px", "padding:10px 4px 8px",
        "background:rgba(255,255,255,.06)", "border:1px solid rgba(255,255,255,.12)",
        "border-radius:10px", "pointer-events:none",
    ]);
    const t = document.createElement("div");
    t.textContent = title;
    t.style.cssText = cssText([
        "font-size:13px", "font-weight:700", "letter-spacing:.3px", "color:" + accent,
    ]);
    const img = document.createElement("img");
    img.src = src;
    img.alt = title;
    img.style.cssText = cssText([
        "width:110px", "height:110px", "object-fit:contain", "display:block",
        "background:#fff", "border-radius:8px", "padding:4px", "box-sizing:border-box",
    ]);
    const c = document.createElement("div");
    c.textContent = caption;
    c.style.cssText = cssText([
        "font-size:11px", "line-height:1.35", "text-align:center",
        "color:var(--fg-color)", "opacity:.85", "word-break:break-all",
    ]);
    card.appendChild(t); card.appendChild(img); card.appendChild(c);
    return { card, img, caption: c };
}

app.registerExtension({
    name: "FxAiBrandNotice",
    beforeRegisterNodeDef(nodeType, nodeData) {
        if (nodeData.name !== "FxAiBrandNotice") return;
        const onNodeCreated = nodeType.prototype.onNodeCreated;
        nodeType.prototype.onNodeCreated = function () {
            const r = onNodeCreated ? onNodeCreated.apply(this, arguments) : undefined;

            for (const w of this.widgets || []) {
                if (w && w.name === "横幅版本") { w.hidden = true; break; }
            }

            // 网页式卡片根节点
            const box = document.createElement("div");
            box.style.cssText = cssText([
                "width:100%", "box-sizing:border-box", "display:flex",
                "flex-direction:column", "gap:10px", "padding:2px",
                "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif",
                "pointer-events:none",
            ]);

            // 品牌头（渐变横幅，纯 CSS，不用图片）
            const head = document.createElement("div");
            head.style.cssText = cssText([
                "display:flex", "align-items:center", "justify-content:space-between",
                "gap:10px", "padding:12px 14px", "border-radius:10px",
                "background:linear-gradient(120deg,#3b82f6,#6366f1,#8b5cf6)",
                "box-shadow:0 2px 10px rgba(99,102,241,.25)",
            ]);
            const headL = document.createElement("div");
            const brandEl = document.createElement("div");
            brandEl.textContent = DEFAULT_CONFIG.brand;
            brandEl.style.cssText = cssText([
                "font-size:20px", "font-weight:800", "color:#fff", "letter-spacing:1px",
            ]);
            const sloganEl = document.createElement("div");
            sloganEl.textContent = DEFAULT_CONFIG.slogan;
            sloganEl.style.cssText = "font-size:12px;color:rgba(255,255,255,.9);margin-top:2px;";
            headL.appendChild(brandEl); headL.appendChild(sloganEl);
            const siteEl = document.createElement("a");
            siteEl.textContent = DEFAULT_CONFIG.site;
            siteEl.href = "https://" + DEFAULT_CONFIG.site.replace(/^https?:\/\//, "");
            siteEl.target = "_blank";
            siteEl.rel = "noopener noreferrer";
            siteEl.title = "点击打开官网";
            siteEl.style.cssText = cssText([
                "font-size:13px", "font-weight:700", "color:#fff", "text-decoration:none",
                "background:rgba(255,255,255,.18)", "padding:5px 10px", "border-radius:20px",
            ]);
            clickable(siteEl);
            head.appendChild(headL); head.appendChild(siteEl);

            // 四二维码并排：QQ群 / 微信 / 视频号（加好友类在前）/ 赞助（收尾）
            const row = document.createElement("div");
            row.style.cssText = cssText([
                "display:flex", "gap:6px", "align-items:stretch",
            ]);
            const qqCard = makeQrCard("QQ群", DEFAULT_CONFIG.qq_qr, "扫码进群", "#60a5fa");
            const spCard = makeQrCard("赞助", DEFAULT_CONFIG.sponsor_qr, DEFAULT_CONFIG.sponsorTip, "#c084fc");
            const wxCard = makeQrCard("微信", DEFAULT_CONFIG.wechat_qr, "扫码加微信", "#34d399");
            const chCard = makeQrCard("视频号", DEFAULT_CONFIG.channel_qr, DEFAULT_CONFIG.channel, "#fb923c");
            row.appendChild(qqCard.card); row.appendChild(wxCard.card);
            row.appendChild(chCard.card); row.appendChild(spCard.card);

            // 底部公告条
            const noticeEl = document.createElement("div");
            noticeEl.textContent = "📢 " + DEFAULT_CONFIG.notice;
            noticeEl.style.cssText = cssText([
                "font-size:12px", "line-height:1.5", "color:var(--fg-color)",
                "padding:10px 12px", "border-radius:8px",
                "background:rgba(139,92,246,.12)", "border-left:3px solid #8b5cf6",
            ]);

            // 云端算力推广条（可点击注册，邀请码随链接自动带入）
            const cloudEl = document.createElement("a");
            cloudEl.href = DEFAULT_CONFIG.cloudUrl;
            cloudEl.target = "_blank";
            cloudEl.rel = "noopener noreferrer";
            cloudEl.title = "注册仙宫云，邀请码 9LWQ36 自动带入";
            cloudEl.style.cssText = cssText([
                "display:flex", "align-items:center", "justify-content:center", "gap:8px",
                "font-size:12px", "font-weight:700", "color:#fff", "text-decoration:none",
                "padding:8px 12px", "border-radius:8px",
                "background:linear-gradient(90deg,#f59e0b,#ea580c)",
            ]);
            const cloudTextEl = document.createElement("span");
            cloudTextEl.textContent = "☁️ " + DEFAULT_CONFIG.cloudText;
            const cloudBtnEl = document.createElement("span");
            cloudBtnEl.textContent = DEFAULT_CONFIG.cloudBtn;
            cloudBtnEl.style.cssText = cssText([
                "background:rgba(255,255,255,.24)", "padding:3px 8px",
                "border-radius:20px", "white-space:nowrap",
            ]);
            cloudEl.appendChild(cloudTextEl); cloudEl.appendChild(cloudBtnEl);
            clickable(cloudEl);

            // 教程入口条（可点击打开）
            const tutorialEl = document.createElement("a");
            tutorialEl.textContent = "📚 " + DEFAULT_CONFIG.tutorial + " → 点击打开";
            tutorialEl.href = DEFAULT_CONFIG.tutorialUrl;
            tutorialEl.target = "_blank";
            tutorialEl.rel = "noopener noreferrer";
            tutorialEl.title = "打开凤希AI实操教程";
            tutorialEl.style.cssText = cssText([
                "display:block", "text-align:center", "font-size:12px", "font-weight:700",
                "color:#fff", "text-decoration:none", "padding:8px 12px", "border-radius:8px",
                "background:linear-gradient(90deg,#0ea5e9,#2563eb)",
            ]);
            clickable(tutorialEl);

            // 下载渠道按钮行（三选一）
            const dlRow = document.createElement("div");
            dlRow.style.cssText = cssText([
                "display:flex", "gap:6px", "justify-content:center",
            ]);
            const dlBtns = [];
            for (const d of DEFAULT_CONFIG.downloads || []) {
                const b = document.createElement("a");
                b.textContent = d.label;
                b.href = d.url;
                b.target = "_blank";
                b.rel = "noopener noreferrer";
                b.title = "打开" + d.label + "下载";
                b.style.cssText = cssText([
                    "flex:1", "text-align:center", "font-size:11px", "font-weight:700",
                    "color:#fff", "text-decoration:none", "padding:6px 4px", "border-radius:6px",
                    "background:" + d.color, "opacity:.92",
                ]);
                clickable(b);
                dlRow.appendChild(b);
                dlBtns.push(b);
            }

            // 连接信息行
            const links = document.createElement("div");
            links.style.cssText = cssText([
                "display:flex", "justify-content:center", "gap:18px",
                "font-size:12px", "color:var(--fg-color)", "opacity:.9",
            ]);
            const qqLink = document.createElement("span"); qqLink.textContent = DEFAULT_CONFIG.qq;
            qqLink.title = "点击复制群号";
            qqLink.style.textDecoration = "underline dotted";
            clickable(qqLink).addEventListener("click", () => copyText(DEFAULT_CONFIG.qq.replace(/[^0-9]/g, ""), qqLink));
            const wxLink = document.createElement("span"); wxLink.textContent = DEFAULT_CONFIG.wechat;
            wxLink.title = "点击复制微信号";
            wxLink.style.textDecoration = "underline dotted";
            clickable(wxLink).addEventListener("click", () => copyText(DEFAULT_CONFIG.wechat.replace(/^微信\s*/, ""), wxLink));
            const invLink = document.createElement("span"); invLink.textContent = DEFAULT_CONFIG.inviter;
            invLink.title = "点击复制邀请码（被邀请/自己填写时用）";
            invLink.style.textDecoration = "underline dotted";
            clickable(invLink).addEventListener("click", () => copyText(DEFAULT_CONFIG.inviter.replace(/[^0-9A-Za-z]/g, ""), invLink));
            links.appendChild(qqLink); links.appendChild(wxLink); links.appendChild(invLink);

            box.appendChild(head); box.appendChild(row);
            box.appendChild(noticeEl); box.appendChild(cloudEl); box.appendChild(tutorialEl); box.appendChild(dlRow); box.appendChild(links);

            this.addDOMWidget("brand_notice", "custom", box, { serialize: false });
            this.brandNoticeBox = box;
            // 用 setSize 而非裸 size=：隐藏 widget 时 ComfyUI 会 computeSize 重算覆盖，
            // 这里设固定尺寸 + onResize 锁宽 + 延迟再锁一次，确保工作流里显示一致。
            const FIX_W = 600, FIX_H = 550;
            this.setSize([FIX_W, FIX_H]);
            this.onResize = function (size) {
                if (size[0] < FIX_W || size[1] < FIX_H) {
                    this.setSize([Math.max(FIX_W, size[0]), Math.max(FIX_H, size[1])]);
                }
            };
            setTimeout(() => {
                this.setSize([FIX_W, FIX_H]);
                if (window.app && app.graph) app.graph.setDirtyCanvas(true, true);
            }, 80);

            // 把配置应用到各元素（本地兜底与远程覆盖共用）
            const apply = (cfg) => {
                if (!cfg || typeof cfg !== "object") return;
                if (cfg.brand)   brandEl.textContent = cfg.brand;
                if (cfg.slogan)  sloganEl.textContent = cfg.slogan;
                if (cfg.site)    {
                    siteEl.textContent = cfg.site;
                    siteEl.href = "https://" + String(cfg.site).replace(/^https?:\/\//, "");
                }
                if (cfg.qq)      { qqLink.textContent = cfg.qq; qqCard.caption.textContent = cfg.qq; }
                if (cfg.cloudText) cloudTextEl.textContent = "☁️ " + cfg.cloudText;
                if (cfg.cloudBtn)  cloudBtnEl.textContent = cfg.cloudBtn;
                if (cfg.cloudUrl)  cloudEl.href = cfg.cloudUrl;
                if (cfg.inviter)   { invLink.textContent = cfg.inviter; }
                if (cfg.tutorial)    { tutorialEl.textContent = "📚 " + cfg.tutorial + " → 点击打开"; }
                if (cfg.tutorialUrl) { tutorialEl.href = cfg.tutorialUrl; }
                if (Array.isArray(cfg.downloads)) {
                    cfg.downloads.forEach((d, i) => {
                        const b = dlBtns[i];
                        if (!b || !d) return;
                        if (d.label) b.textContent = d.label;
                        if (d.url) b.href = d.url;
                        if (d.color) b.style.background = d.color;
                    });
                }
                if (cfg.wechat)  { wxLink.textContent = cfg.wechat; wxCard.caption.textContent = cfg.wechat; }
                if (cfg.sponsorTip) spCard.caption.textContent = cfg.sponsorTip;
                if (cfg.notice)  noticeEl.textContent = "📢 " + cfg.notice;
                if (cfg.qq_qr)      qqCard.img.src = cfg.qq_qr;
                if (cfg.sponsor_qr) spCard.img.src = cfg.sponsor_qr;
                if (cfg.wechat_qr)  wxCard.img.src = cfg.wechat_qr;
                if (cfg.channel)    chCard.caption.textContent = cfg.channel;
                if (cfg.channel_qr) chCard.img.src = cfg.channel_qr;
            };

            // 远程动态配置：依次尝试各源，谁先成功就用谁覆盖；全失败则保持内嵌默认。
            // 本地默认已经先渲染，所以网络不稳/离线时显示完全正常，无红节点。
            (function loadRemote(i) {
                if (!REMOTE_CONFIG_URLS || i >= REMOTE_CONFIG_URLS.length) return;
                const url = REMOTE_CONFIG_URLS[i] + (REMOTE_CONFIG_URLS[i].includes("?") ? "&" : "?") + "t=" + Date.now();
                const ctl = new AbortController();
                const timer = setTimeout(() => ctl.abort(), CONFIG_TIMEOUT_MS);
                fetch(url, { cache: "no-store", signal: ctl.signal })
                    .then((resp) => { if (!resp.ok) throw new Error("HTTP " + resp.status); return resp.json(); })
                    .then((cfg) => { clearTimeout(timer); apply(cfg); })   // 覆盖本地默认
                    .catch(() => { clearTimeout(timer); loadRemote(i + 1); }) // 换下一个源
            })(0);

            return r;
        };
    },
});
